// ── 5. The three-way agreement invariant (CREATED by this plan) ────────────

describe('three-way agreement (C0)', () => {
  function composeRichSession() {
    const entry = makeEntry();
    const ctx = composeCtx(entry, { sessionId: 'sess_rich' });
    // dispatcher answered
    ctx.recordAskProduced({
      producerId: 'dispatcher_ask',
      runtimeId: 'toolu_r1',
      liveAskKey: K('r1'),
    });
    ctx.recordAskEmitted({ runtimeId: 'toolu_r1' });
    ctx.recordAskResolved({
      runtimeId: 'toolu_r1',
      terminal: 'answered',
      detail: { answer_frame_id: 'toolu_r1', transcript_resolved: true },
    });
    // dialogue answered + a rejected attempt first (stays visible, uncreditable)
    ctx.recordAskProduced({
      producerId: 'dialogue_script_ask',
      runtimeId: 'srv_r1',
      liveAskKey: K('r2'),
    });
    ctx.recordAskEmitted({ runtimeId: 'srv_r1' });
    ctx.recordAskResolved({
      runtimeId: 'srv_r1',
      terminal: 'answered',
      detail: { answer_frame_id: 'srv_r1', transcript_resolved: false },
    });
    ctx.recordAskResolved({
      runtimeId: 'srv_r1',
      terminal: 'answered',
      detail: { answer_frame_id: 'srv_r1', transcript_resolved: true },
    });
    // address-mirror answered + reissue
    ctx.recordAskProduced({
      producerId: 'address_mirror_ask',
      runtimeId: 'q_r1',
      liveAskKey: K('r3'),
    });
    ctx.recordAskEmitted({ runtimeId: 'q_r1' });
    ctx.recordAskEmitted({ runtimeId: 'q_r1' }); // same-id re-send → reissued_attempt
    ctx.recordAskResolved({
      runtimeId: 'q_r1',
      terminal: 'answered',
      detail: { answer_frame_id: 'q_r1', transcript_resolved: true },
    });
    // deliveries in every family + playbacks
    const op1 = {
      extractionTurnId: 'tA',
      field: 'measured_zs_ohm',
      circuit: 4,
      boardId: null,
      ordinal: 0,
    };
    const op2 = {
      extractionTurnId: 'tB',
      field: 'r1_r2_ohm',
      circuit: 7,
      boardId: null,
      ordinal: 0,
    };
    const op3 = {
      extractionTurnId: 'tC',
      field: 'client_address',
      circuit: null,
      boardId: null,
      ordinal: 0,
    };
    ctx.recordDelivery([op1], {
      producerId: 'result_frame_confirmation',
      kind: 'confirmation',
      wireTurnId: 'tA',
    });
    ctx.recordDelivery([op2], {
      producerId: 'dialogue_confirmation',
      kind: 'dialogue_confirmation',
    });
    ctx.recordDelivery([op3], {
      producerId: 'address_mirror_terminal',
      kind: 'address_mirror_terminal',
      claimLineage: 'result:tok_r',
    });
    ctx.recordPlayback({ ok: 1 }, [op1], { producerId: 'playback_ack_slot', source: 'ordinary' });
    ctx.recordPlayback({ ok: 2 }, [op3], {
      producerId: 'address_mirror_delivery_ack',
      source: 'address_mirror_delivery_ack',
    });
    // round usage (sub-records only — excluded from the comparable subset)
    ctx.roundUsageSink(
      { provider: 'openai', api_transport: 'responses', round_idx: 0 },
      { loopInvocationId: 'loop_r', billableKind: 'inspector_extraction' }
    );
    return entry;
  }

  test('latched-snapshot reconstruction and frozen-ledger projection agree (eligible session)', () => {
    const entry = composeRichSession();
    const frozen = freezeEvidenceCompletion(entry, {
      sessionId: 'sess_rich',
      boundary: 'session_stopped',
    });
    expect(frozen.eligible).toBe(true);
    const fromSnapshot = buildEvidenceProjectionV1(frozen.candidate);
    const fromLedgers = projectFrozenLedgersV1(frozen);
    expect(comparableSubset(fromSnapshot)).toEqual(comparableSubset(fromLedgers));
    // and the rejected attempt is visible on the sub-records side only
    expect(fromSnapshot.ask_families.dialogue_script.rejected).toHaveLength(1);
    expect(fromSnapshot.family_gates.dialogue_script.ask_lifecycle_complete).toBe(true);
    expect(fromSnapshot.family_gates.address_mirror.playback_ack_proof).toBe(true);
  });

  test('agreement holds for an ineligible session (open ask + invalid latch)', () => {
    const entry = makeEntry();
    const ctx = composeCtx(entry, { sessionId: 'sess_bad' });
    ctx.recordAskProduced({
      producerId: 'dialogue_script_ask',
      runtimeId: 'srv_open',
      liveAskKey: K('b1'),
    });
    ctx.recordAskEmitted({ runtimeId: 'srv_open' });
    ctx.reserveFastTts({
      correlationId: 'corr_b',
      candidate: { field: 'x', circuit: null, board_id: null, value: '1' },
    });
    const frozen = freezeEvidenceCompletion(entry, {
      sessionId: 'sess_bad',
      boundary: 'session_stopped',
    });
    expect(frozen.eligible).toBe(false);
    const fromSnapshot = buildEvidenceProjectionV1(frozen.candidate);
    const fromLedgers = projectFrozenLedgersV1(frozen);
    expect(comparableSubset(fromSnapshot)).toEqual(comparableSubset(fromLedgers));
    expect(fromSnapshot.eligible_for_family_credit).toBe(false);
    expect(fromSnapshot.ineligible_conditions).toEqual([
      { condition: 'delivery_invalid', reason: 'fast_provisional_unconsumed', count: null },
    ]);
  });

  test('the retained object-identity immutability check still holds beside the new invariant', () => {
    const entry = composeRichSession();
    const frozen = freezeEvidenceCompletion(entry, {
      sessionId: 'sess_rich2',
      boundary: 'session_stopped',
    });
    expect(frozen.evidence.sub_records).toBe(frozen.candidate.sub_records);
    expect(Object.isFrozen(frozen.evidence.sub_records)).toBe(true);
  });
});

// ── 5b. The windowed-judge quiescence carve-out (C2) ───────────────────────

describe('windowed-judge carve-out — open-Tier-2-ask-ONLY non-quiescence (C2)', () => {
  test('an open dialogue_script ask at stop no longer holds the WINDOWED judge (00C counts stay strict)', () => {
    const entry = makeEntry();
    const ctx = composeCtx(entry, { sessionId: 'sess_jw' });
    ctx.recordAskProduced({
      producerId: 'dialogue_script_ask',
      runtimeId: 'srv_jw',
      liveAskKey: K('jw'),
    });
    ctx.recordAskEmitted({ runtimeId: 'srv_jw' });
    const frozen = freezeEvidenceCompletion(entry, {
      sessionId: 'sess_jw',
      boundary: 'session_stopped',
    });
    // the FREEZE stays strict: ineligible, counts carry the open ask — this
    // is exactly what 00C's completion fold consumes
    expect(frozen.eligible).toBe(false);
    expect(frozen.counts.open_asks_dialogue_script).toBe(1);
    expect(frozen.counts.non_quiescent_at_stop).toBe(1);
    // the carve-out is OPT-IN (Codex r1 B-2/C-4): with no declared window
    // the judge is STRICT; only a caller declaring dialogue_script as
    // window-external proceeds (a stable open ask mutates nothing, and
    // dialogue asks are outside the corpus observation boundary).
    expect(composeCaptureInvalid(frozen)).toEqual({ reason: 'non_quiescent_at_stop' });
    expect(
      composeCaptureInvalid(frozen, { windowedOpenAskFamilies: ['dialogue_script'] })
    ).toBeNull();
  });

  test('an open DISPATCHER ask never passes the carve-out, even with a declared window', () => {
    const entry = makeEntry();
    const ctx = composeCtx(entry, { sessionId: 'sess_jw3' });
    ctx.recordAskProduced({
      producerId: 'dispatcher_ask',
      runtimeId: 'toolu_jw3',
      liveAskKey: K('jw3'),
    });
    ctx.recordAskEmitted({ runtimeId: 'toolu_jw3' });
    const frozen = freezeEvidenceCompletion(entry, {
      sessionId: 'sess_jw3',
      boundary: 'session_stopped',
    });
    expect(frozen.eligible).toBe(false);
    // dispatcher asks are window-OBSERVABLE — the carve-out never covers them
    expect(composeCaptureInvalid(frozen, { windowedOpenAskFamilies: ['dialogue_script'] })).toEqual(
      { reason: 'non_quiescent_at_stop' }
    );
  });

  test('any OTHER non-quiescence beside the open ask still holds the judge', () => {
    const entry = makeEntry();
    entry.isExtracting = true; // an in-flight extraction CAN still mutate evidence
    const ctx = composeCtx(entry, { sessionId: 'sess_jw2' });
    ctx.recordAskProduced({
      producerId: 'dialogue_script_ask',
      runtimeId: 'srv_jw2',
      liveAskKey: K('jw2'),
    });
    ctx.recordAskEmitted({ runtimeId: 'srv_jw2' });
    const frozen = freezeEvidenceCompletion(entry, {
      sessionId: 'sess_jw2',
      boundary: 'session_stopped',
    });
    expect(frozen.eligible).toBe(false);
    expect(composeCaptureInvalid(frozen, { windowedOpenAskFamilies: ['dialogue_script'] })).toEqual(
      { reason: 'non_quiescent_at_stop' }
    );
  });
});

